CREATE proc [dbo].[uspKotDeptWiseWithOutDeals] @OrderKey nvarchar(50),@TiltId as int as select d.department_name,i.category_name,ok.ItemId,i.item_name,ok.ItemComment,i.sale_price,ok.OrderKey,sum(ok.Qty) as Qty,ok.KotStatus,ok.Comments,p.printer,'' as DealDepartment,'' as DealPrinter,'' as DealItem from DepartmentPOS d inner join  CategoryPOS c on d.Department_Name = c.Department  left join Printer_Setup p on p.department = d.Department_Name  inner join ItemPOS i on i.Category_Name = c.Category_Name   inner join OrderKot ok on i.Id = ok.ItemId   where ok.OrderKey = @OrderKey and KotStatus <> 1 and p.[document] = 'KOT (Department)'  and i.category_name <>'DealsOnSpot' group by  d.department_name,i.category_name, ok.ItemId,i.item_name,ok.ItemComment,i.sale_price,ok.OrderKey,ok.KotStatus,ok.Comments,p.printer  select *,'Dpt' as Dpt from dine_in_order di  inner join Shift_Opening so on di.z_number = so.z_report_number  where di.order_key = @OrderKey  